import sys

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    playlist = []
    for _ in range(n):
        ci = int(data[index])
        ti = int(data[index + 1])
        index += 2
        playlist.append((ci, ti))

    queries = [int(data[index + i]) for i in range(m)]

    current_time = 0
    result = []
    for query in queries:
        while current_time < query:
            if playlist[0][0] > 0:
                playlist[0] = (playlist[0][0] - 1, playlist[0][1])
                current_time += playlist[0][1]
                if playlist[0][0] == 0:
                    del playlist[0]
            else:
                break

        if len(playlist) > 0:
            result.append(1)
        else:
            result.append(-1)

    for r in result:
        print(r)

if __name__ == "__main__":
    main()
